<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { refreshCsrfToken, sessionUser, session } from '../data/session'
import {
	readPortalState,
	removePortalState,
	STORAGE_TTL,
	writePortalState,
} from '../data/portalStorage'
import { statusPillClass as statusClass } from '../data/dataPengajuanStatus'
import { htmlToText, notifyError } from '../composables/toast'
import { canUseCamera, capturePhoto } from '../composables/cameraCapture'
import SelectMenu from '../components/SelectMenu.vue'
import FotoPengajuanAttachments from '../components/FotoPengajuanAttachments.vue'

const router = useRouter()

// Nilai field (reactive). status mulai 'Draft' (initial state workflow Flow Kredit)
// → field mandatory_depends_on(status=="Draft") ikut wajib, sesuai Frappe.
const form = reactive({ status: 'Draft' })

// ── Draft autosave ──────────────────────────────────────────────────────────
// Isian form create disimpan otomatis ke localStorage supaya TIDAK hilang saat
// user kembali ke Home atau keluar/berpindah aplikasi. Semua nilai `form`
// serializable: lampiran & File Kredit disimpan sebagai URL hasil upload
// (bukan objek File), jadi cukup serialize `form` apa adanya.
// Draft dikunci per-user, dan dibersihkan setelah submit berhasil.
let _draftRestored = false // jangan menyimpan sebelum restore (hindari menimpa isi lama dengan default)
let _submitted = false // setelah submit sukses: berhenti menyimpan agar draft tak dibuat ulang saat unmount
let _saveTimer = null

function draftKey() {
	return `dp_draft:${session.user || 'anon'}`
}
function saveDraft() {
	if (!_draftRestored || _submitted) return
	writePortalState(
		'draft',
		session.user,
		'DataPengajuanCreate',
		{ form },
		{
			ttlMs: STORAGE_TTL.DRAFT,
		},
	)
}
function saveDraftNow() {
	if (_saveTimer) {
		clearTimeout(_saveTimer)
		_saveTimer = null
	}
	saveDraft()
}
function restoreDraft() {
	let parsed = readPortalState('draft', session.user, 'DataPengajuanCreate', undefined)
	try {
		const raw = window.localStorage.getItem(draftKey())
		const legacy = raw ? JSON.parse(raw) : null
		if (!parsed && legacy?.v === 1 && legacy.form && typeof legacy.form === 'object') {
			parsed = { form: legacy.form }
			writePortalState('draft', session.user, 'DataPengajuanCreate', parsed, {
				ttlMs: STORAGE_TTL.DRAFT,
			})
		}
		window.localStorage.removeItem(draftKey())
	} catch (e) {
		/* draft rusak — abaikan */
	}
	if (parsed?.form && typeof parsed.form === 'object') Object.assign(form, parsed.form)
	_draftRestored = true
}
function clearDraft() {
	_submitted = true
	removePortalState('draft', session.user, 'DataPengajuanCreate')
	try {
		window.localStorage.removeItem(draftKey())
	} catch {}
}
function onVisibilityChange() {
	// App di-background (pindah app / kunci layar) → simpan segera.
	if (document.visibilityState === 'hidden') saveDraftNow()
}

// Simpan otomatis (debounced) setiap isian berubah.
watch(
	form,
	() => {
		if (_saveTimer) clearTimeout(_saveTimer)
		_saveTimer = setTimeout(saveDraft, 400)
	},
	{ deep: true },
)

// Kembali ke Home / komponen di-unmount → simpan segera + lepas listener.
onBeforeUnmount(() => {
	saveDraftNow()
	document.removeEventListener('visibilitychange', onVisibilityChange)
	window.removeEventListener('pagehide', saveDraftNow)
})

// Nama Marketing = user yang login (read-only). Server controller juga set
// marketing=user_id, TAPI fetch_from marketing_full_name jalan SEBELUM itu
// (urutan save Frappe) → kalau tidak kita isi dari sini, nama di list kosong.
// Maka kita set marketing + marketing_full_name dari User Juragan user aktif.
const marketingDisplay = ref('')
async function loadMarketing() {
	const user = sessionUser()
	if (!user) return
	form.marketing = user
	marketingDisplay.value = user // fallback sementara
	try {
		const params = new URLSearchParams({ doctype: 'User Juragan', name: user })
		const res = await fetch(`/api/method/frappe.client.get?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			cache: 'no-store',
			headers: { Accept: 'application/json' },
		})
		const doc = (await res.json())?.message
		const nama = (doc && doc.nama_lengkap) || ''
		if (nama) {
			form.marketing_full_name = nama
			marketingDisplay.value = nama
		}
		// Cabang TERISI OTOMATIS dari User Juragan marketing (persis controller desk:
		// self.cabang = User Juragan.cabang). Field cabang read-only, bukan manual.
		if (doc && doc.cabang) form.cabang = doc.cabang
	} catch (e) {
		/* biarkan fallback = email */
	}
}

// Tampilan nilai field read-only (Currency/Link/lainnya) di form create.
function readOnlyText(field) {
	const v = form[field.fieldname]
	if (v == null || v === '') return '—'
	if (field.fieldtype === 'Currency') return currencyDisplay(v)
	if (field.fieldtype === 'Link') return linkDisplay(field) || v
	return v
}

const saving = ref(false)
const saveError = ref('')

// ---- Meta doctype ----------------------------------------------------------
const metaFields = ref([])
// Batas lampiran dari DocType (max_attachments) — dipakai untuk cegatan di klien.
const maxAttachments = ref(0)
const metaError = ref('')

// ---- Akses permlevel (persis desk) -----------------------------------------
// Sumber kebenaran = Meta.get_permlevel_access server (endpoint get_permlevel_access).
// Field pada permlevel yang TAK boleh dibaca user → disembunyikan; yang boleh baca
// tapi tak boleh tulis → read-only. Ini menyamakan visibilitas form create portal
// dengan desk (mis. Sales User hanya boleh permlevel 0; CMO 0/1/4/5 dst).
const readablePermlevels = ref(new Set([0]))
const writablePermlevels = ref(new Set([0]))
const prosesPencairanEnabled = ref(false)
const fotoPengajuanEnabled = ref(false)
const prosesPencairanLoaded = ref(false)
const prosesPencairanError = ref('')
async function loadPermlevelAccess() {
	prosesPencairanLoaded.value = false
	prosesPencairanError.value = ''
	try {
		const params = new URLSearchParams({ doctype: 'Data Pengajuan' })
		const res = await fetch(
			`/api/method/juragan.api.portal.meta.get_permlevel_access?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } },
		)
		if (!res.ok) throw new Error(`HTTP ${res.status}`)
		const msg = (await res.json()).message || {}
		if (
			typeof msg.enable_proses_pencairan_pengajuan !== 'boolean' ||
			typeof msg.enable_foto_pengajuan !== 'boolean'
		) {
			throw new Error('Feature flag tidak tersedia pada respons server.')
		}
		prosesPencairanEnabled.value = msg.enable_proses_pencairan_pengajuan === true
		fotoPengajuanEnabled.value = msg.enable_foto_pengajuan === true
		if (Array.isArray(msg.read)) readablePermlevels.value = new Set([0, ...msg.read])
		if (Array.isArray(msg.write)) writablePermlevels.value = new Set([0, ...msg.write])
	} catch (e) {
		prosesPencairanError.value = `Pengaturan lampiran tidak dapat dimuat: ${e.message || e}`
	} finally {
		prosesPencairanLoaded.value = true
	}
}
function canReadPermlevel(f) {
	return readablePermlevels.value.has(f.permlevel || 0)
}
function canWritePermlevel(f) {
	return writablePermlevels.value.has(f.permlevel || 0)
}

// ---- Tab top-level (fungsi) -----------------------------------------------
// Halaman Add hanya menampilkan Data & Attachments. Activity & Comments tidak
// ada di sini karena dokumen belum tersimpan (belum ada record untuk ditautkan);
// keduanya tersedia di halaman Detail setelah data disimpan.
const TABS = [
	{
		key: 'data',
		label: 'Data',
		icon: '<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18"/><path d="M9 21V9"/>',
	},
	{
		key: 'attachments',
		label: 'Attachments',
		icon: '<path d="m21.44 11.05-9.19 9.19a6 6 0 0 1-8.49-8.49l8.57-8.57A4 4 0 1 1 18 8.84l-8.59 8.57a2 2 0 0 1-2.83-2.83l8.49-8.48"/>',
	},
]
const activeTab = ref('data')

// Semua tab yang tersisa (Data & Attachments) selalu bisa diakses.
function tabEnabled() {
	return true
}

// Sub-tab di dalam tab "Data" (= Tab Break dari meta doctype).
const activeSubtab = ref('')

// Kelas input form (isi field text-xs; tombol & heading pakai ukuran natural-nya).
const inputClass =
	'min-h-[44px] w-full rounded-md border border-ui-line-gray-300 bg-ui-surface px-3 py-2 text-base text-ui-ink-gray-800 outline-none transition focus:border-primary focus:ring-2 focus:ring-inset focus:ring-primary/30 md:min-h-0'

// Susun tab → section → kolom → field dari meta (urut sesuai idx asli).
const dataTabs = computed(() => {
	const tabs = []
	let curTab = null
	let curSection = null
	let curCol = null
	for (const f of metaFields.value) {
		const ft = f.fieldtype
		if (ft === 'Tab Break') {
			// Photos and disbursement notes are only available after the document is saved.
			if (['foto_tab', 'proses_pencairan_tab'].includes(f.fieldname)) {
				curTab = null
				curSection = null
				curCol = null
				continue
			}
			curTab = { key: f.fieldname, label: f.label || f.fieldname, sections: [] }
			tabs.push(curTab)
			curSection = null
			curCol = null
			continue
		}
		if (!curTab) continue
		if (ft === 'Section Break') {
			curCol = []
			curSection = { label: f.label || '', depends_on: f.depends_on, columns: [curCol] }
			curTab.sections.push(curSection)
			continue
		}
		if (ft === 'Column Break') {
			if (!curSection) {
				curCol = []
				curSection = { label: '', columns: [curCol] }
				curTab.sections.push(curSection)
			} else {
				curCol = []
				curSection.columns.push(curCol)
			}
			continue
		}
		// Lewati field non-input / yang ditangani terpisah (Attach & child table →
		// dilengkapi di detail setelah dokumen dibuat).
		if (
			[
				'HTML',
				'Button',
				'Heading',
				'Fold',
				'Image',
				'Barcode',
				'Table',
				'Table MultiSelect',
				'Attach',
				'Attach Image',
			].includes(ft)
		)
			continue
		if (f.hidden) continue
		// permlevel tanpa hak baca → sembunyikan (persis form desk). Mis. Sales User
		// hanya boleh permlevel 0, jadi field nasabah/kendaraan (permlevel 1) hilang.
		if (!canReadPermlevel(f)) continue
		if (f.depends_on && !evalCondition(f.depends_on)) continue
		// Field read-only yang masih KOSONG → sembunyikan (jangan tampilkan "—").
		// Mis. `kategori_enduser` terkunci sampai status "Proses CA"; di form create
		// dokumen selalu baru, jadi cukup disembunyikan selama belum ada isinya.
		if (isFieldReadOnly(f)) {
			const v = form[f.fieldname]
			if (v == null || v === '') continue
		}
		if (!curSection) {
			curCol = []
			curSection = { label: '', columns: [curCol] }
			curTab.sections.push(curSection)
		}
		curCol.push(f)
	}
	for (const t of tabs) {
		t.sections = t.sections
			.filter((s) => evalCondition(s.depends_on))
			.map((s) => ({ ...s, columns: s.columns.filter((c) => c.length) }))
			.filter((s) => s.columns.length)
	}
	return tabs
})

// Daftar sub-tab (label) untuk strip di dalam tab "Data".
const SUBTABS = computed(() => dataTabs.value.map((t) => ({ key: t.key, label: t.label })))

const sectionsForActiveSubtab = computed(() => {
	const t = dataTabs.value.find((x) => x.key === activeSubtab.value)
	return t ? t.sections : []
})

// Field Attach (File Kredit) → dirender di tab Attachments (di-stage ke payload insert).
const attachFields = computed(() =>
	metaFields.value.filter((f) => ['Attach', 'Attach Image'].includes(f.fieldtype) && !f.hidden),
)

// Jumlah lampiran yang benar-benar dirujuk form — cara hitung yang sama dengan
// server (data_pengajuan/attachments.py). Satu URL bisa dipakai dua tempat kalau
// isi filenya identik & di-dedup Frappe, jadi dihitung sebagai satu.
const attachmentTotal = computed(() => {
	const urls = new Set()
	for (const f of attachFields.value) {
		const url = (form[f.fieldname] || '').trim()
		if (url) urls.add(url)
	}
	for (const row of form.table_otkl || []) {
		const url = (row.upload_file_pdf_png_jpg || '').trim()
		if (url) urls.add(url)
	}
	for (const row of form.foto_pengajuan || []) {
		const url = (row.foto || '').trim()
		if (url) urls.add(url)
	}
	return urls.size
})

// Cegat sebelum upload supaya user tahu kuotanya habis sejak awal, bukan baru saat
// Simpan. Server tetap yang jadi penentu. `replacing` = mengganti file yang sudah
// ada → tidak menambah slot.
function attachmentQuotaError(replacing = false) {
	if (replacing || !maxAttachments.value || attachmentTotal.value < maxAttachments.value)
		return ''
	return `Maksimal ${maxAttachments.value} lampiran per pengajuan. Hapus file lain dulu.`
