}
function isNumberField(ft) {
	return ['Int', 'Float', 'Currency', 'Percent'].includes(ft)
}

// Evaluasi ekspresi kondisi Frappe (depends_on / mandatory_depends_on) thd form.
function evalCondition(expr) {
	if (!expr) return true
	try {
		const code = String(expr).replace(/^eval:/, '')
		const in_list = (list, item) => Array.isArray(list) && list.includes(item)
		const cint = (v) => parseInt(v, 10) || 0
		const cstr = (v) => (v == null ? '' : String(v))
		const flt = (v) => parseFloat(v) || 0
		// Shim `frappe.session.user` supaya depends_on admin-only (mis. Status Geocoding)
		// dievaluasi benar, bukan gagal → fail-open (tampil untuk semua).
		const frappe = {
			session: { user: sessionUser() },
			boot: {
				enable_proses_pencairan_pengajuan: prosesPencairanEnabled.value,
				enable_foto_pengajuan: fotoPengajuanEnabled.value,
			},
		}
		// eslint-disable-next-line no-new-func
		return !!new Function(
			'doc',
			'in_list',
			'cint',
			'cstr',
			'flt',
			'frappe',
			`return (${code})`,
		)(form, in_list, cint, cstr, flt, frappe)
	} catch (e) {
		return true
	}
}
function isFieldReqd(field) {
	if (field.reqd) return true
	return field.mandatory_depends_on ? evalCondition(field.mandatory_depends_on) : false
}

// Read-only saat create: hormati read_only statis DAN read_only_depends_on (persis
// doctype). Dokumen baru tak pernah berstatus "Proses CA", jadi field seperti
// `kategori_enduser` (read_only_depends_on: status != "Proses CA") otomatis terkunci
// di form create — hanya bisa diisi nanti di detail saat Proses CA oleh role
// berhak (permlevel 1: CMO, Credit Analyst, Pimcab, Pembanding, IT Administrator).
function isFieldReadOnly(field) {
	// Tak punya hak tulis permlevel → read-only (persis form desk).
	if (!canWritePermlevel(field)) return true
	// read_only_depends_on MENIMPA read_only statis (persis set_dependant_property desk):
	// mis. provinsi_domisili (read_only=1 + dep CA Rejected/Banding) → editable saat baru.
	if (field.read_only_depends_on) return evalCondition(field.read_only_depends_on)
	return !!field.read_only
}

// ---- Currency --------------------------------------------------------------
function formatCurrency(v) {
	const n = Number(v)
	if (v === '' || v == null || Number.isNaN(n)) return String(v ?? '')
	return new Intl.NumberFormat('id-ID', {
		minimumFractionDigits: 2,
		maximumFractionDigits: 2,
	}).format(n)
}
function currencyDisplay(v) {
	if (v === '' || v == null || Number.isNaN(Number(v))) return ''
	return `Rp ${formatCurrency(v)}`
}
function parseCurrency(str) {
	if (str == null) return ''
	const cleaned = String(str)
		.replace(/\./g, '')
		.replace(',', '.')
		.replace(/[^\d.]/g, '')
	if (cleaned === '') return ''
	const n = Number(cleaned)
	return Number.isNaN(n) ? '' : n
}
function onCurrencyBlur(field, e) {
	const n = parseCurrency(e.target.value)
	form[field.fieldname] = n
	e.target.value = currencyDisplay(n)
}

