const linkTitleField = reactive({})
const linkTitles = reactive({})
const linkOptions = reactive({})

async function loadLinkMeta() {
	const dts = new Set()
	for (const f of metaFields.value) {
		if (f.fieldtype === 'Link' && f.options) dts.add(f.options)
	}
	await Promise.all(
		[...dts].map(async (dt) => {
			let titleField = null
			try {
				const res = await fetch(
					`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(
						dt,
					)}`,
					{
						method: 'GET',
						credentials: 'include',
						headers: { Accept: 'application/json' },
					},
				)
				const json = await res.json()
				const docs = json.docs || json.message?.docs || []
				const meta = docs.find((x) => x.name === dt) || docs[0]
				titleField = (meta && meta.title_field) || null
				linkTitleField[dt] = titleField
			} catch (e) {
				linkTitleField[dt] = null
			}
			try {
				const flds = titleField ? ['name', titleField] : ['name']
				const lparams = new URLSearchParams({
					doctype: dt,
					fields: JSON.stringify(flds),
					limit_page_length: '101',
					order_by: 'name asc',
				})
				const lres = await fetch(
					`/api/method/frappe.client.get_list?${lparams.toString()}`,
					{
						method: 'GET',
						credentials: 'include',
						headers: { Accept: 'application/json' },
					},
				)
				const ljson = await lres.json()
				const recs = ljson.message || []
				if (recs.length && recs.length <= 100) {
					linkOptions[dt] = recs.map((r) => ({
						value: String(r.name),
						label: (titleField && r[titleField]) || String(r.name),
					}))
				}
			} catch (e) {
				// abaikan → fallback ke fetch saat dibuka
			}
		}),
	)
}

function linkDisplay(field) {
	const v = form[field.fieldname]
	if (!v) return ''
	const opts = linkOptions[field.options]
	if (opts) {
		const cur = opts.find((o) => String(o.value).toLowerCase() === String(v).toLowerCase())
		if (cur) return cur.label
	}
	const t = linkTitles[`${field.options}:${v}`]
	return t !== undefined ? t : v
}

const openDropdown = ref('')
// Arah buka dropdown: true = ke atas (saat ruang di bawah trigger tidak cukup,
// mis. field terakhir "Data Kendaraan" yang tertutup tombol Save).
const dropUp = ref(false)
const linkSearch = ref('')
const linkResults = ref([])
const linkSearchLoading = ref(false)

// Filter bawaan Link dari Frappe (`link_filters`) → array [field, op, value] utk
// dikirim ke get_list, supaya opsi yang tampil SAMA dengan desk (mis. hanya data
// `aktif=1`). Tanpa ini, opsi non-aktif ikut muncul lalu ditolak server (mis.
// controller Data Pengajuan me-null `model` non-aktif → "Value missing: Model").
// Kondisi dinamis (eval:/referensi doc) dilewati karena tak bisa dievaluasi di klien.
// Cascade filter domisili — meniru client script desk "Dynamic Select Domisili".
// provinsi_domisili fixed "Kepulauan Riau" (kode 21): Kota difilter provinsi,
// Kecamatan difilter kota terpilih, Kelurahan difilter kecamatan (+kota guard)
// terpilih. Nilai '' saat parent belum dipilih → hasil kosong (paksa urutan isi).
const PROV_CODE_DOMISILI = '21' // Kepulauan Riau
const domisiliFilters = {
	kota_domisili: () => [['kode_provinsi', '=', PROV_CODE_DOMISILI]],
	kecamatan_domisili: () => [['kode_kab_kota', '=', form.kota_domisili || '']],
	kelurahan_domisili: () => [
		['kode_kecamatan', '=', form.kecamatan_domisili || ''],
		['kode_kab_kota', '=', form.kota_domisili || ''],
	],
	kota_domisili_pps: () => [['kode_provinsi', '=', PROV_CODE_DOMISILI]],
	kecamatan_domisili_pps: () => [['kode_kab_kota', '=', form.kota_domisili_pps || '']],
	kelurahan_domisili_pps: () => [
		['kode_kecamatan', '=', form.kecamatan_domisili_pps || ''],
		['kode_kab_kota', '=', form.kota_domisili_pps || ''],
	],
}
// Parent berubah → kosongkan turunannya (spt set_value(null) di client script desk).
const domisiliChildren = {
	kota_domisili: ['kecamatan_domisili', 'kelurahan_domisili'],
	kecamatan_domisili: ['kelurahan_domisili'],
	kota_domisili_pps: ['kecamatan_domisili_pps', 'kelurahan_domisili_pps'],
	kecamatan_domisili_pps: ['kelurahan_domisili_pps'],
}

function linkFilters(field) {
	const out = []
	const push = (f, op, v) => {
		const isDyn = typeof v === 'string' && /^eval:|^doc\./.test(v.trim())
		if (!isDyn) {
			out.push([f, op, v])
			return
		}
		// Resolusi nilai DINAMIS terhadap form (mis. "eval: doc.tenor" → nilai tenor
		// terpilih) supaya filter ikut nilai form — mis. Skema Pinjaman hanya tenor
		// yang dipilih. Belum ada nilai (tenor belum dipilih) → filter dilewati.
		let val
		try {
			const s = v.trim()
			// eslint-disable-next-line no-new-func
			val = s.startsWith('eval:')
				? new Function('doc', `return (${s.slice(5)})`)(form)
				: form[s.slice(4)]
		} catch (e) {
			val = undefined
		}
		if (val === undefined || val === null || val === '') return
		out.push([f, op, val])
	}
	// Filter bawaan Link dari Frappe (`link_filters`).
	let raw = field.link_filters
	if (raw) {
		try {
			if (typeof raw === 'string') raw = JSON.parse(raw)
		} catch (e) {
			raw = null
		}
		if (Array.isArray(raw)) {
			for (const c of raw) {
				if (!Array.isArray(c)) continue
				if (c.length === 4) push(c[1], c[2], c[3])
				else if (c.length === 3) push(c[0], c[1], c[2])
			}
		} else if (raw && typeof raw === 'object') {
			for (const [k, v] of Object.entries(raw)) push(k, '=', v)
		}
	}
	// Cascade domisili (tak ada di link_filters doctype; disetel via client script desk).
	const dom = domisiliFilters[field.fieldname]
	if (dom) out.push(...dom())
	return out
}

function optionMatch(opt, field) {
	const v = form[field.fieldname]
	if (v == null || v === '') return false
	return String(opt.value).toLowerCase() === String(v).toLowerCase()
}
// Perkiraan tinggi panel dropdown (search box + list max-h-56). Dipakai untuk
// memutuskan buka ke atas / ke bawah agar tidak tertutup tombol Save.
const DROPDOWN_EST_HEIGHT = 300
function toggleLinkDropdown(field, event) {
	if (openDropdown.value === field.fieldname) {
		openDropdown.value = ''
		return
	}
	// Tentukan arah: kalau ruang di bawah trigger kurang DAN ruang di atas lebih
	// lega, buka ke atas. Ini yang mencegah dropdown menutupi tombol Save.
	const rect = event?.currentTarget?.getBoundingClientRect?.()
	if (rect) {
		const spaceBelow = window.innerHeight - rect.bottom
		const spaceAbove = rect.top
		dropUp.value = spaceBelow < DROPDOWN_EST_HEIGHT && spaceAbove > spaceBelow
	} else {
		dropUp.value = false
	}
	openDropdown.value = field.fieldname
	linkSearch.value = ''
	// Field dgn link_filters / penjualan_mokas → selalu fetch (jangan pakai cache generik).
	const opts =
		field.fieldname === 'penjualan_mokas' || linkFilters(field).length
			? null
			: linkOptions[field.options]
	if (opts) linkResults.value = opts
	else fetchLinkResults(field, '')
}
async function fetchLinkResults(field, query) {
	// Penjualan Mokas → query terfilter dealer (get_penjualan_mokas_query), bukan get_list.
	if (field.fieldname === 'penjualan_mokas') return fetchPenjualanMokas(query)
	const dt = field.options
	const titleField = linkTitleField[dt]
	linkSearchLoading.value = true
	linkResults.value = []
	try {
		const flds = titleField ? ['name', titleField] : ['name']
		const params = new URLSearchParams({
			doctype: dt,
			fields: JSON.stringify(flds),
			limit_page_length: '20',
			order_by: 'name asc',
		})
		const lf = linkFilters(field)
		if (lf.length) params.set('filters', JSON.stringify(lf))
		if (query) {
			const ors = [['name', 'like', `%${query}%`]]
			if (titleField) ors.push([titleField, 'like', `%${query}%`])
			params.set('or_filters', JSON.stringify(ors))
		}
		const res = await fetch(`/api/method/frappe.client.get_list?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json()
		const recs = json.message || []
		linkResults.value = recs.map((r) => ({
			value: String(r.name),
			label: (titleField && r[titleField]) || String(r.name),
		}))
	} catch (e) {
		linkResults.value = []
	} finally {
		linkSearchLoading.value = false
	}
}
let linkSearchTimer = null
function onLinkSearch(field) {
	const q = linkSearch.value.trim()
	const opts =
		field.fieldname === 'penjualan_mokas' || linkFilters(field).length
			? null
			: linkOptions[field.options]
	if (opts) {
		const ql = q.toLowerCase()
		linkResults.value = ql
			? opts.filter(
					(o) =>
						o.label.toLowerCase().includes(ql) ||
						String(o.value).toLowerCase().includes(ql),
				)
			: opts
		return
	}
	clearTimeout(linkSearchTimer)
	linkSearchTimer = setTimeout(() => fetchLinkResults(field, q), 300)
}
// Tiru perilaku `fetch_from` Frappe: saat sebuah Link berubah, langsung isi
// field turunannya dari dokumen tertaut TANPA perlu save (persis form desk).
// Mis. pinjam ← skema_pinjaman.pinjaman, angsuran ← skema_pinjaman.angsuran.
async function applyFetchFrom(linkField, value) {
	const prefix = `${linkField.fieldname}.`
	const targets = metaFields.value.filter(
		(f) => typeof f.fetch_from === 'string' && f.fetch_from.startsWith(prefix),
	)
	if (!targets.length) return
	// Link dikosongkan → kosongkan juga field turunannya.
	if (!value) {
		for (const t of targets) form[t.fieldname] = null
		return
	}
	const sourceFields = targets.map((t) => t.fetch_from.slice(prefix.length))
	try {
		const params = new URLSearchParams({
			doctype: linkField.options,
			filters: JSON.stringify({ name: value }),
			fieldname: JSON.stringify(sourceFields),
		})
		const res = await fetch(`/api/method/frappe.client.get_value?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		if (!res.ok) return
		const data = (await res.json())?.message || {}
		for (const t of targets) {
			const src = t.fetch_from.slice(prefix.length)
			if (src in data) form[t.fieldname] = data[src]
		}
	} catch (e) {
		/* abaikan — nilai tetap akan ikut terisi server saat save (fallback) */
	}
}

function selectLink(field, value, label) {
	const prev = form[field.fieldname]
	form[field.fieldname] = value
	if (label != null) linkTitles[`${field.options}:${value}`] = label
	openDropdown.value = ''
	// Isi otomatis field ber-fetch_from (mis. Pinjaman & Angsuran dari Skema Pinjaman).
	applyFetchFrom(field, value)
	// Cascade domisili: parent berubah → kosongkan turunannya (spt client script desk).
	if (prev !== value) {
		const children = domisiliChildren[field.fieldname]
		if (children) for (const c of children) form[c] = null
	}
}

