async function fetchPenjualanMokas(query) {
	linkSearchLoading.value = true
	linkResults.value = []
	try {
		// Lewat search_link (persis frm.set_query desk): ia mem-parse `filters` &
		// meneruskan ke custom query get_penjualan_mokas_query, lalu format autosuggest.
