			txt: query || '',
			query: 'juragan.juragan.doctype.data_pengajuan.data_pengajuan.get_penjualan_mokas_query',
			filters: JSON.stringify({ dealer_mokas: form.nama_dealer || '', pengajuan: '' }),
			page_length: '20',
		})
		const res = await fetch(
			`/api/method/frappe.desk.search.search_link?${params.toString()}`,
			{
				method: 'GET',
				credentials: 'include',
				headers: { Accept: 'application/json' },
			},
		)
		const recs = (await res.json())?.message || []
		// recs = [{ value: name, description: "nopol, merk, model", label }]
		linkResults.value = recs.map((r) => ({
			value: String(r.value),
			label: r.description || String(r.value),
		}))
	} catch (e) {
		linkResults.value = []
	} finally {
		linkSearchLoading.value = false
	}
}

