// ---- Load meta -------------------------------------------------------------
async function loadMeta() {
	try {
		const res = await fetch(
			`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(
				'Data Pengajuan',
			)}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } },
		)
		if (!res.ok) throw new Error(`HTTP ${res.status}`)
		const json = await res.json()
		const docs = json.docs || json.message?.docs || []
		const dt = docs.find((x) => x.name === 'Data Pengajuan') || docs[0]
		metaFields.value = (dt && dt.fields) || []
		maxAttachments.value = Number(dt && dt.max_attachments) || 0
		applyDefaults()
		if (!activeSubtab.value && dataTabs.value.length) {
			activeSubtab.value = dataTabs.value[0].key
		}
		await loadLinkMeta()
	} catch (e) {
		metaError.value = e.message || String(e)
	}
}

// Terapkan `default` field dari meta doctype (persis form baru desk). Ini yang
// mengisi mis. provinsi_domisili = "Kepulauan Riau", tanggal default "Today",
// dll — supaya field read-only ber-default tetap terisi & lolos validasi.
function applyDefaults() {
	for (const f of metaFields.value) {
		const cur = form[f.fieldname]
		if (cur !== undefined && cur !== null && cur !== '') continue // sudah diisi
		const def = f.default
		if (def == null || def === '') continue
		if (f.fieldtype === 'Date' && String(def).toLowerCase() === 'today') {
			const d = new Date()
			form[f.fieldname] = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(
				2,
				'0',
			)}-${String(d.getDate()).padStart(2, '0')}`
		} else if (f.fieldtype === 'Check') {
			form[f.fieldname] = parseInt(def, 10) ? 1 : 0
		} else if (isNumberField(f.fieldtype)) {
			form[f.fieldname] = Number(def) || 0
		} else {
			form[f.fieldname] = def
		}
	}
}

// ---- Submit ----------------------------------------------------------------
// Validasi field wajib (reqd / mandatory_depends_on) lintas tab.
function validate() {
	const missing = []
	for (const f of allFields.value) {
		if (!isFieldReqd(f)) continue
		const v = form[f.fieldname]
		if (v === undefined || v === null || v === '') missing.push(f.label || f.fieldname)
	}
	return missing
}

// Ekstrak pesan error Frappe yang manusiawi dari response.
function frappeError(json) {
	try {
		if (json && json._server_messages) {
			const arr = JSON.parse(json._server_messages)
			return htmlToText(
				arr
					.map((m) => {
						try {
							return JSON.parse(m).message
						} catch (e) {
							return m
						}
					})
					.join('\n'),
			)
		}
	} catch (e) {
		/* ignore */
	}
	return htmlToText((json && (json.exception || json.message)) || '')
}

// ---- Attachments: File Kredit (Attach) + child table File Pendukung --------
// This page has no saved docname. Uploads become available on the detail page
// after submit() creates the pengajuan; keep a guard against stale handlers.
async function uploadRawFile(file) {
	throw new Error('Simpan pengajuan terlebih dahulu sebelum mengunggah lampiran.')
}

// Batas & validasi file (ekstensi + ukuran). `exts` = daftar ekstensi yang boleh.
const MAX_FILE_MB = 3
function validateFile(file, exts) {
	const ext = (file.name.split('.').pop() || '').toLowerCase()
	if (!exts.includes(ext)) {
		return `Format file harus ${exts.map((e) => e.toUpperCase()).join(', ')}.`
	}
	if (file.size > MAX_FILE_MB * 1024 * 1024) {
		return `Ukuran file maksimal ${MAX_FILE_MB} MB.`
	}
	return ''
}

// --- File Kredit (field Attach: ktp / ktp_2 / ktp_3) — hanya PDF ---
const kreditInput = ref(null)
const pendingKreditField = ref(null)
const kreditUploading = ref('')
const kreditError = ref('')

function triggerKreditPick(f) {
	pendingKreditField.value = f
	kreditError.value = ''
	if (kreditInput.value) {
		kreditInput.value.value = '' // reset → file sama bisa dipilih ulang
		kreditInput.value.click()
	}
}
async function onKreditFileChange(e) {
	const file = e.target.files && e.target.files[0]
	const f = pendingKreditField.value
	if (!file || !f) return
	// Hanya PDF, maks 3 MB.
	const err = validateFile(file, ['pdf'])
	if (err) {
		kreditError.value = `${f.label}: ${err}`
		pendingKreditField.value = null
		return
	}
	const qerr = attachmentQuotaError(Boolean(form[f.fieldname]))
	if (qerr) {
		kreditError.value = qerr
		pendingKreditField.value = null
		return
	}
	kreditUploading.value = f.fieldname
	kreditError.value = ''
	try {
		const fileDoc = await uploadRawFile(file)
		form[f.fieldname] = fileDoc.file_url
	} catch (err2) {
		kreditError.value = err2.message || String(err2)
	} finally {
		kreditUploading.value = ''
		pendingKreditField.value = null
	}
}

// --- File Pendukung (child table table_otkl → "File Upload Data Pendukung") ---
const attachmentRows = computed(() => form.table_otkl || [])
// Tombol "Ambil Foto" hanya ditampilkan di dalam aplikasi native; di browser
// atribut `capture` diabaikan sehingga tombolnya mubazir (lihat cameraCapture.js).
const showCameraButton = canUseCamera()
const pendukungInput = ref(null)
const pendukung = reactive({
	namaFile: '',
	submitting: false,
	error: '',
})
// Opsi Nama File → master "File Tambahan Data Pengajuan" (name = nama file).
const pendukungOptions = ref([])

function resetPendukungForm() {
	pendukung.namaFile = ''
	pendukung.error = ''
	if (pendukungInput.value) pendukungInput.value.value = ''
}
function triggerPendukungPick() {
	if (pendukungInput.value) {
		pendukungInput.value.value = ''
		pendukungInput.value.click()
	}
}
function triggerPendukungCamera() {
	if (!pendukung.namaFile) {
		pendukung.error = 'Pilih Nama File terlebih dulu.'
		return
	}
	capturePhoto().then(uploadPendukungFile)
}
async function onPendukungFileChange(e) {
	await uploadPendukungFile(e.target.files && e.target.files[0])
}
// Pilih file / ambil foto → LANGSUNG upload + tambah baris (tanpa tombol Tambah).
// Syarat: Nama File sudah dipilih; file JPG/PNG/PDF maks 3 MB.
async function uploadPendukungFile(file) {
	if (!file) return
	pendukung.error = ''
	if (!pendukung.namaFile) {
		pendukung.error = 'Pilih Nama File terlebih dulu.'
		if (pendukungInput.value) pendukungInput.value.value = ''
		return
	}
	const err = validateFile(file, ['jpg', 'jpeg', 'png', 'pdf'])
	if (err) {
		pendukung.error = err
		if (pendukungInput.value) pendukungInput.value.value = ''
		return
	}
	const qerr = attachmentQuotaError()
	if (qerr) {
		pendukung.error = qerr
		if (pendukungInput.value) pendukungInput.value.value = ''
		return
	}
	pendukung.submitting = true
	try {
		const fileDoc = await uploadRawFile(file)
		if (!Array.isArray(form.table_otkl)) form.table_otkl = []
		form.table_otkl.push({
			doctype: 'File Upload Data Pendukung',
			parentfield: 'table_otkl',
			parenttype: 'Data Pengajuan',
			nama_file: pendukung.namaFile,
			upload_file_pdf_png_jpg: fileDoc.file_url,
		})
		resetPendukungForm()
	} catch (e2) {
		pendukung.error = e2.message || String(e2)
	} finally {
		pendukung.submitting = false
	}
}
async function loadPendukungOptions() {
	try {
		const params = new URLSearchParams({
			doctype: 'File Tambahan Data Pengajuan',
			fields: JSON.stringify(['name']),
			limit_page_length: '0',
			order_by: 'name asc',
		})
		const res = await fetch(`/api/method/frappe.client.get_list?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json()
		pendukungOptions.value = (json.message || []).map((r) => r.name)
	} catch (e) {
		pendukungOptions.value = []
	}
}
function removePendukungRow(idx, row) {
	if (!Array.isArray(form.table_otkl)) return
	const label = row?.nama_file ? `"${row.nama_file}"` : 'baris ini'
	askConfirm(`Hapus ${label} dari File Pendukung?`, () => {
		if (!Array.isArray(form.table_otkl)) return
		form.table_otkl.splice(idx, 1)
	})
}

// Hapus File Kredit (staged) → kosongkan nilai field, dengan konfirmasi.
function deleteKreditFile(f) {
	askConfirm(`Hapus file pada "${f.label}"?`, () => {
		form[f.fieldname] = ''
	})
}

// ---- Modal konfirmasi in-app (pengganti window.confirm) -------------------
const confirmDialog = reactive({ open: false, title: '', message: '', onConfirm: null })
function askConfirm(message, onConfirm, title = 'Konfirmasi Hapus') {
	confirmDialog.title = title
	confirmDialog.message = message
	confirmDialog.onConfirm = onConfirm
	confirmDialog.open = true
}
function confirmYes() {
	const fn = confirmDialog.onConfirm
	confirmDialog.open = false
	confirmDialog.onConfirm = null
	if (typeof fn === 'function') fn()
}
function confirmNo() {
	confirmDialog.open = false
	confirmDialog.onConfirm = null
}

async function submit() {
	saveError.value = ''
	const missing = validate()
	if (missing.length) {
		saveError.value = `Lengkapi field wajib: ${missing.join(', ')}`
		window.scrollTo({ top: 0, behavior: 'smooth' })
		return
	}
	saving.value = true
	try {
		await refreshCsrfToken()
		const res = await fetch('/api/method/frappe.client.insert', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ doc: { doctype: 'Data Pengajuan', ...form } }),
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		// Submit berhasil → buang draft supaya form berikutnya bersih.
		clearDraft()
		const name = json.message?.name
		if (name) {
			router.push({ name: 'DataPengajuanDetail', params: { name } })
		} else {
			router.push({ name: 'DataPengajuan' })
		}
	} catch (e) {
		saveError.value = e.message || String(e)
		window.scrollTo({ top: 0, behavior: 'smooth' })
	} finally {
		saving.value = false
	}
}

// ---- Offset sticky (DIUKUR dinamis) — sama seperti halaman Detail -----------
// Header, tab utama, & sub-tab semuanya sticky; posisi `top` tab & sub-tab dihitung
// dari tinggi elemen di atasnya supaya tidak ada celah/tumpang-tindih.
const headerRef = ref(null)
const tabStripRef = ref(null)
const tabTop = ref(0) // sticky tab utama = tinggi header
const subTop = ref(0) // sticky sub-tab = tinggi header + tab utama
function measureSticky() {
	const h = headerRef.value?.offsetHeight || 0
	const t = tabStripRef.value?.offsetHeight || 0
	// Overlap 1px tiap bar → tidak ada celah rambut dari pembulatan sub-pixel.
	tabTop.value = Math.max(0, h - 1)
	subTop.value = Math.max(0, tabTop.value + t - 1)
}
let _stickyRO = null
function setupStickyObservers() {
	if (typeof ResizeObserver === 'undefined') return
	_stickyRO = new ResizeObserver(() => measureSticky())
	if (headerRef.value) _stickyRO.observe(headerRef.value)
	if (tabStripRef.value) _stickyRO.observe(tabStripRef.value)
}
watch(activeTab, () => nextTick(measureSticky))
onBeforeUnmount(() => {
	_stickyRO?.disconnect()
	window.removeEventListener('resize', measureSticky)
})

onMounted(async () => {
	await refreshCsrfToken()
	// Pulihkan draft SEBELUM loadMeta/applyDefaults & sebelum dealerReady aktif:
	// applyDefaults hanya mengisi field kosong (nilai draft menang), dan watcher
	// dealer masih non-aktif sehingga tidak mengosongkan field saat restore.
	restoreDraft()
	document.addEventListener('visibilitychange', onVisibilityChange)
	window.addEventListener('pagehide', saveDraftNow)
	loadMarketing()
	await loadPermlevelAccess()
	await loadMeta()
	syncEndUserBbg()
	loadPendukungOptions()
	// Unit internal (MOKAS): muat daftar dealer & hitung flag awal, lalu aktifkan
	// watcher dealer supaya tidak jalan saat inisialisasi default.
	await loadDealerMokasList()
	await syncDealerMokasFlag({ clearUnit: false })
	dealerReady.value = true
	// Elemen header & tab strip sudah ter-render → ukur tinggi untuk offset sticky.
	await nextTick()
	measureSticky()
	setupStickyObservers()
	window.addEventListener('resize', measureSticky)
})
